"wissen": {
  "meta": {
    "title": "Lexikon & Tudásbázis | K-Aqua Akadémia",
    "desc": "K-Aqua Lexikon: Fejtse meg az ipari csővezeték-technológia szakkifejezéseit. Az SDR-től a polimer fúzióig – German Engineering megmagyarázva."
  },
  "scroll": {
    "items": [
      {
        "title": "A Polimerek Molekuláris Fölénye",
        "desc": "A fémcsövek felületi kezelésre és a falvastagság túlzott méretezésére támaszkodnak a korrózió kompenzálása érdekében. A K-Aqua PP-R (Polypropylene Random Kopolimer) azonban molekuláris szinten oldja meg a problémát. Teljesen semleges, taszítja az elektrokémiai reakciókat, és évtizedekig megőrzi a tökéletesen sima belső felületét (k=0,007 mm)."
      },
      {
        "title": "Termodinamika a Csőben",
        "desc": "Az energia drága, a hőveszteség pedig elfogadhatatlan a modern épületgépészeti rendszerekben. A fémek kiváló hővezetők, és ez a hátrányuk a hűtésben vagy a fűtésben. A K-Aqua PP-R természetes hőszigetelő tulajdonságaival (0,24 W/mK) masszív energiamegtakarítást ér el a folyadék szállítása során anélkül, hogy vastag kiegészítő szigetelésre lenne szükség."
      },
      {
        "title": "Hegesztés ragasztás helyett: Homogén Fúzió",
        "desc": "Ahol a műanyag rendszereket ragasztják (pl. PVC) vagy menettel kötik (O-gyűrűk fémcsövek esetén), a hőciklusok során mikroszivárgások (szivárgások) keletkeznek. A mi válaszunk: Molekuláris hegesztés. Az anyag átmenetileg megolvad és 100%-ban homogén csatlakozást képez. Nincs gyenge pont, nincs tömítés, nincs kompromisszum."
      },
      {
        "title": "Kavitációs Ellenállás és Áramlásmechanika",
        "desc": "Az ultrasima belső fal (érdesség < 0,007 mm) révén a K-Aqua csövek nullához közeli értékre csökkentik az áramlási ellenállást. Ez megakadályozza a biofilmek kialakulását és kiküszöböli a mikro-kavitációs hatásokat a nagy sebességű áramlásoknál. A rendszer nyomásvesztesége drasztikusan csökken, ami maximalizálja a csatlakoztatott szivattyúrendszerek energiahatékonyságát ipari méretekben."
      }
    ]
  },
  "bento": {
    "eyebrow": "Nómenklatúra",
    "title": "Műszaki Paraméterek.",
    "lead": "Az ipari csővezeték-technológia legfontosabb szókincse a lényegre desztillálva.",
    "items": [
      {
        "title": "PP-R (Polypropylene Random Kopolimer)",
        "desc": "A molekuláris alap. Egy nagykristályos, hőre lágyuló polimer, amely kivételes ellenállást nyújt a magas hőmérsékletekkel és nyomásokkal szemben. Ez a tartósságunk DNS-e."
      },
      {
        "title": "Lineáris Hőtágulás",
        "desc": "Az anyag hosszváltozása hőmérséklet-változáskor. Szálerősítésű (Faser) csöveink ezt az értéket az abszolút minimumra csökkentik (α = 0,035 mm/mK), ami jelentősen növeli a szerkezeti stabilitást az aknákban."
      },
      {
        "title": "Kúszási Szilárdság (Időtállóság)",
        "desc": "A rendszer azon képessége, hogy évtizedeken át ellenálljon a folyamatos belső nyomásnak meghatározott hőmérsékleteken anélkül, hogy deformálódna vagy felrobbanna. A K-Aqua csövek 50+ évre vannak kalibrálva."
      },
      {
        "title": "Nyomásveszteségi Együttható",
        "desc": "Egy matematikai érték, amely a cső belső falán fellépő súrlódás okozta áramlási energiaveszteséget írja le. A nanoszintű sima felületeknek köszönhetően ez az érték a K-Aqua rendszerekben marginális."
      },
      {
        "title": "SDR (Standard Dimension Ratio)",
        "desc": "A külső átmérő (d) és a falvastagság (s) aránya. Egy SDR 6 cső lényegesen nagyobb nyomást bír el, mint egy SDR 11 cső. A helyes választás kulcsfontosságú a rendszertervezés szempontjából.",
        "label": "50+ ÉV"
      }
    ]
  },
